package net.vibmc.network.packetevents.codec;
import com.github.retrooper.packetevents.netty.buffer.ByteBufHelper;import io.netty.buffer.*;import io.netty.channel.ChannelHandlerContext;import io.netty.handler.codec.*;import java.util.List;
public final class PacketSplitter extends ByteToMessageDecoder{protected void decode(ChannelHandlerContext c,ByteBuf b,List<Object> out){b.markReaderIndex();ByteBuf length=Unpooled.buffer(5);try{for(int i=0;i<5;i++){if(!b.isReadable()){b.resetReaderIndex();return;}byte value=b.readByte();length.writeByte(value);if(value>=0){int size=ByteBufHelper.readVarInt(length);if(size<0||size>1<<20)throw new CorruptedFrameException("Invalid frame length");if(b.readableBytes()<size){b.resetReaderIndex();return;}out.add(b.readRetainedSlice(size));return;}}throw new CorruptedFrameException("VarInt frame length exceeds 5 bytes");}finally{length.release();}}}
